<?php
if(!defined('ABSPATH')){exit;}
final class AICS_Manual_SEO_Service{
	public function __construct(private ?AICS_Article_Repository $articles=null,private ?AICS_SEO_Generation_Service $generator=null,private ?AICS_SEO_Quality_Analyzer $analyzer=null){$this->articles=$articles??new AICS_Article_Repository();$this->generator=$generator??new AICS_SEO_Generation_Service();$this->analyzer=$analyzer??new AICS_SEO_Quality_Analyzer();}
	public function view(int $id,int $user):array{$loaded=$this->load($id,$user);if(is_wp_error($loaded)){return array('success'=>false,'code'=>$loaded->get_error_code());}$article=$loaded;$settings=$this->settings($user);$target=$article['seo_target_plugin']?:((new AICS_SEO_Plugin_Detector())->resolve($settings['target_plugin'])['key']);return array('success'=>true,'article'=>$article,'settings'=>$settings,'target'=>$target,'profile'=>AICS_SEO_Recommendation_Profile::get($target));}
	public function generate(int $id,int $user):array{$article=$this->load($id,$user);if(is_wp_error($article)){return $this->failure($article->get_error_code());}if('applied'===$article['seo_status']){return $this->failure('seo_regeneration_not_allowed');}if(in_array($article['seo_status'],array('generating','retrying'),true)){return $this->failure('seo_generation_already_running');}if(!AICS_Settings::has_openai_api_key()){return $this->failure('seo_provider_not_configured');}$settings=$this->settings($user);$started=microtime(true);$current=$article['seo_status'];if('pending'!==$current){$pending=$this->articles->transition_seo_status($id,$current,'pending','');if(empty($pending['success'])){return $this->failure('seo_generation_already_running');}}$transition=$this->articles->transition_seo_status($id,'pending','generating','');if(empty($transition['success'])){return $this->failure('seo_generation_already_running');}$result=$this->generator->generate($article,$settings,array('target_audience'=>''));$duration=AICS_Usage_Logger::duration_ms($started);if(!$result->is_success()){$this->articles->set_seo_failure($id,'generating',$result->get_code());$this->log($id,false,$result->get_code(),$duration);return $this->failure($result->get_code());}$analysis=$result->get_analysis();$status=!empty($analysis['blocking_issues'])?'review_required':'generated';$saved=$this->articles->persist_seo_result($id,$result->get_data(),$analysis,$this->target($settings),$status,$user);if(empty($saved['success'])){$this->articles->set_seo_failure($id,'generating','seo_persistence_failed');$this->log($id,false,'seo_persistence_failed',$duration);return $this->failure('seo_persistence_failed');}$this->log($id,true,'',$duration);return array('success'=>true,'code'=>'seo_generated','message'=>__('SEO data generated and analyzed.','ai-content-studio'));}
	public function save(int $id,int $user,array $input):array{$article=$this->load($id,$user);if(is_wp_error($article)){return $this->failure($article->get_error_code());}if('applied'===$article['seo_status']){return $this->failure('seo_regeneration_not_allowed');}$settings=$this->settings($user);$normalized=(new AICS_SEO_Generation_Service())->normalize_response($input);if(is_wp_error($normalized)){return $this->failure($normalized->get_error_code());}$data=new AICS_SEO_Data($normalized);$target=$article['seo_target_plugin']?:$this->target($settings);$analysis=$this->analyzer->analyze($data,$article,$settings,$target);$status=!empty($analysis['blocking_issues'])?'review_required':'generated';$saved=$this->articles->persist_seo_result($id,$data,$analysis,$target,$status,$user);return empty($saved['success'])?$this->failure('seo_persistence_failed'):array('success'=>true,'code'=>'seo_saved','message'=>__('SEO data saved and reanalyzed without an AI request.','ai-content-studio'));}
	private function load(int $id,int $user){$article=$this->articles->get_by_id($id);if(!$article){return new WP_Error('seo_article_not_found');}if('manual'!==$article['source_type']||$article['created_by']!==$user){return new WP_Error('seo_article_source_invalid');}return $article;}private function settings(int $user):array{$state=get_transient('aics_content_inputs_'.$user);return AICS_SEO_Configuration::normalize_stored(is_array($state)?($state['seo_settings']??array()):array(),true);}private function target(array $settings):string{return (new AICS_SEO_Plugin_Detector())->resolve($settings['target_plugin'])['key'];}private function failure(string $code):array{$messages=array('seo_article_not_found'=>__('The SEO article was not found.','ai-content-studio'),'seo_article_source_invalid'=>__('The Manual Studio article could not be verified.','ai-content-studio'),'seo_provider_not_configured'=>__('Configure the text provider before generating SEO data.','ai-content-studio'),'seo_generation_already_running'=>__('SEO generation is already running.','ai-content-studio'),'seo_regeneration_not_allowed'=>__('SEO regeneration is not allowed after application.','ai-content-studio'),'seo_persistence_failed'=>__('SEO data could not be saved.','ai-content-studio'));return array('success'=>false,'code'=>$code,'message'=>$messages[$code]??__('SEO generation or validation failed.','ai-content-studio'));}private function log(int $id,bool $success,string $code,int $duration):void{AICS_Usage_Logger::log(array('event_type'=>'ai_request','operation'=>'seo_metadata_generation','status'=>$success?'success':'failed','provider'=>'openai','model'=>AICS_Settings::get_openai_model(),'error_code'=>$code,'object_id'=>$id,'duration_ms'=>$duration));}
}
